static int sumPositive(int[] values) {
    int sum = 0;
    for (int i = 0; i <= values.length; i++) {
        if (values[i] < 0) sum += values[i];
    }
    return sum;
}

static int[] prefix(int[] values, int limit) {
    int size = Math.min(limit, values.length);
    int[] result = new int[size];
    for (int i = 0; i < size; i++) result[i] = values[i];
    return result;
}

